#include <stdio.h>

int max_of(int arr[], int n) {
    int best = arr[0];              // начинаем с первого, а не с нуля:
    for (int i = 1; i < n; i++) {   // иначе для отрицательных чисел ответ будет неверным
        if (arr[i] > best) {
            best = arr[i];
        }
    }
    return best;
}

int main(void) {
    int data[] = {3, 17, 8, 42, 5};
    printf("%d\n", max_of(data, 5));   // 42
    return 0;
}

