#include <stdio.h>

void reverse(int *arr, int n) {
    int left = 0, right = n - 1;
    while (left < right) {          // идём навстречу друг другу
        int tmp = arr[left];
        arr[left] = arr[right];
        arr[right] = tmp;
        left++;
        right--;
    }
}

int main(void) {
    int data[5] = {1, 2, 3, 4, 5};
    reverse(data, 5);
    for (int i = 0; i < 5; i++) {
        printf("%d ", data[i]);
    }
    printf("\n");
    return 0;
}

