#include <stdio.h>

int count_words(const char *s) {
    int words = 0;
    int inside = 0;                  // находимся ли сейчас внутри слова
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] == ' ') {
            inside = 0;
        } else if (!inside) {        // начало нового слова
            inside = 1;
            words++;
        }
    }
    return words;
}

int main(void) {
    printf("%d\n", count_words("c is  a  language"));
    return 0;
}

