/* qsort передаёт указатели на элементы — их надо привести к своему типу */
int cmp_int(const void* a, const void* b) {
    int x = *(const int*)a;
    int y = *(const int*)b;
    return (x > y) - (x < y);        /* безопаснее, чем x - y: не переполнится */
}

typedef struct { char name[16]; int score; } Player;

int cmp_player(const void* a, const void* b) {
    const Player* p = (const Player*)a;
    const Player* q = (const Player*)b;
    return q->score - p->score;      /* по убыванию очков */
}

int main(void) {
