    while (n < 16 && fscanf(f, "%15s %d", players[n].name, &players[n].score) == 2)
        n++;
    fclose(f);

    qsort(players, n, sizeof(Player), cmp_desc);

    for (int i = 0; i < n; i++)
        printf("%d. %s %d\n", i + 1, players[i].name, players[i].score);
